1	import Foundation
2	
3	/// A conclusion the trend analysis reached.  Wording lives with the view — this
4	/// type carries only which conclusions apply, so the rules and their thresholds
5	/// can be tested and shared across platforms.
6	enum NinebotTripInsight: String, Codable, CaseIterable, Identifiable {
7	    /// One ride is far longer than the daily average, so range estimates lean
8	    /// harder on recent samples.
9	    case longRideDominates
10	    /// Average electricity used per ride is high.
11	    case highAverageElectricity
12	    /// Energy per kilometre is high.
13	    case highEnergyPerKm
14	    /// Not enough verified range samples yet.
15	    case fewRangeSamples
16	    /// Local recordings exist that are not linked to an interface ride.
17	    case unlinkedLocalRides
18	    /// Nothing notable — emitted only when no other insight applies.
19	    case normal
20	
21	    var id: String { rawValue }
22	}
23	
24	/// Aggregates a month of rides into the figures the trend screen shows.
25	///
26	/// Derived from the `TripTrendAnalysis` that used to live inside
27	/// NinebotDashboardView. Numbers and rules live here; the `...Text` properties
28	/// that format them for display are a view-layer extension.
29	struct NinebotTripTrend {
30	    var snapshot: NinebotVehicleSnapshot
31	    var recordedRides: [NinebotRecordedRide]
32	
33	    // MARK: - Rule thresholds
34	    //
35	    // These decide which insights fire.  They were inline literals inside the
36	    // view; naming them is the point of pulling this type out.
37	
38	    /// A single ride longer than the daily average by this factor counts as a
39	    /// long ride.
40	    static let longRidePeakRatio = 1.8
41	    /// Average electricity per ride above this (Wh) counts as high.
42	    static let highAverageElectricityWh = 12.0
43	    /// Energy per kilometre above this (Wh/km) counts as high.
44	    static let highEnergyPerKmWh = 35.0
45	    /// Fewer verified range samples than this counts as not enough.
46	    static let sufficientRangeSampleCount = 5
47	    /// How many recent rides the ride list shows.
48	    static let recentRideDisplayCount = 8
49	
50	    // MARK: - Source collections
51	
52	    var dailyRecords: [NinebotDailyMileageRecord] {
53	        snapshot.state.dailyMileages.sorted {
54	            if let left = $0.date, let right = $1.date {
55	                return left < right
56	            }
57	            return $0.day < $1.day
58	        }
59	    }
60	
61	    var rides: [NinebotRideRecord] {
62	        snapshot.state.rides
63	    }
64	
65	    var recentRides: [NinebotRideRecord] {
66	        Array(rides.prefix(Self.recentRideDisplayCount))
67	    }
68	
69	    var rideCount: Int {
70	        rides.count
71	    }
72	
73	    var activeDayCount: Int {
74	        dailyRecords.count
75	    }
76	
77	    // MARK: - Aggregates
78	
79	    var monthMileage: Double? {
80	        if let monthMileage = snapshot.state.monthMileage {
81	            return monthMileage
82	        }
83	        guard !dailyRecords.isEmpty else { return nil }
84	        return dailyRecords.reduce(0) { $0 + $1.mileage }
85	    }
86	
87	    var averageDailyMileage: Double? {
88	        guard let monthMileage, !dailyRecords.isEmpty else { return nil }
89	        return monthMileage / Double(dailyRecords.count)
90	    }
91	
92	    var averageSpeed: Double? {
93	        let samples = rides.compactMap(\.speed).filter { $0 > 0 }
94	        guard !samples.isEmpty else { return nil }
95	        return samples.reduce(0, +) / Double(samples.count)
96	    }
97	
98	    var averageUsedElectricity: Double? {
99	        let samples = rides.compactMap(\.usedElectricity).filter { $0 > 0 }
100	        guard !samples.isEmpty else { return nil }
101	        return samples.reduce(0, +) / Double(samples.count)
102	    }
103	
104	    var peakRideMileage: Double? {
105	        rides.compactMap(\.mileage).max()
106	    }
107	
108	    /// Prefers the month totals when available, otherwise averages per-ride
109	    /// energy over per-ride distance.
110	    var energyPerKm: Double? {
111	        if let monthMileage, monthMileage > 0,
112	           let energy = snapshot.state.monthUsedElectricity ?? snapshot.state.monthEnergy {
113	            return energy / monthMileage
114	        }
115	
116	        let samples = rides.compactMap { ride -> Double? in
117	            guard let mileage = ride.mileage, mileage > 0,
118	                  let energy = ride.energy, energy > 0 else { return nil }
119	            return energy / mileage
120	        }
121	        guard !samples.isEmpty else { return nil }
122	        return samples.reduce(0, +) / Double(samples.count)
123	    }
124	
125	    // MARK: - Rules
126	
127	    /// Which conclusions apply, in display order.  Never empty: falls back to
128	    /// `.normal` when nothing else fires.
129	    var insights: [NinebotTripInsight] {
130	        var result: [NinebotTripInsight] = []
131	
132	        if let peak = peakRideMileage,
133	           let averageDailyMileage,
134	           peak > averageDailyMileage * Self.longRidePeakRatio {
135	            result.append(.longRideDominates)
136	        }
137	
138	        if let averageUsedElectricity, averageUsedElectricity > Self.highAverageElectricityWh {
139	            result.append(.highAverageElectricity)
140	        }
141	
142	        if let energyPerKm, energyPerKm > Self.highEnergyPerKmWh {
143	            result.append(.highEnergyPerKm)
144	        }
145	
146	        if snapshot.state.observedRangeSampleCount < Self.sufficientRangeSampleCount {
147	            result.append(.fewRangeSamples)
148	        }
149	
150	        if recordedRides.contains(where: { $0.associatedRideID == nil }) {
151	            result.append(.unlinkedLocalRides)
152	        }
153	
154	        if result.isEmpty {
155	            result.append(.normal)
156	        }
157	
158	        return result
159	    }
160	}
