304	struct NinebotInterfaceTrackPoint: Equatable, Identifiable {
305	    var id: String
306	    var latitude: Double
307	    var longitude: Double
308	    var speedKmh: Double?
309	    var auxiliaryValue: Double?
310	
311	    var coordinate: CLLocationCoordinate2D {
312	        CLLocationCoordinate2D(latitude: latitude, longitude: longitude)
