316	extension NinebotRideDetail {
317	    var interfaceTrackPoints: [NinebotInterfaceTrackPoint] {
318	        let points = Self.bestTrackPoints(from: raw)
319	        if !points.isEmpty {
320	            return points
321	        }
322	        return interfaceTrackCoordinates.enumerated().map { index, coordinate in
323	            Self.interfaceTrackPoint(
324	                coordinate: coordinate,
325	                speedKmh: nil,
326	                auxiliaryValue: nil,
327	                index: index
328	            )
329	        }
330	    }
331	
332	    var interfaceTrackCoordinates: [CLLocationCoordinate2D] {
333	        let points = Self.bestTrackPoints(from: raw)
334	        if !points.isEmpty {
335	            return points.map(\.coordinate)
336	        }
337	        return Self.bestTrackCoordinates(from: raw)
338	    }
339	
340	    private static func bestTrackPoints(from value: JSONValue) -> [NinebotInterfaceTrackPoint] {
341	        let candidateValues = trackCandidateValues(from: value)
342	        let parsedCandidates = candidateValues
343	            .map { trackPoints(from: $0) }
344	            .filter { $0.count > 1 }
345	
346	        return parsedCandidates.max { $0.count < $1.count } ?? []
347	    }
348	
349	    private static func bestTrackCoordinates(from value: JSONValue) -> [CLLocationCoordinate2D] {
350	        let candidateValues = trackCandidateValues(from: value)
351	        let parsedCandidates = candidateValues
352	            .map { trackCoordinates(from: $0) }
353	            .filter { $0.count > 1 }
354	
355	        return parsedCandidates.max { $0.count < $1.count } ?? []
356	    }
357	
358	    private static func trackCandidateValues(from value: JSONValue) -> [JSONValue] {
359	        let trackKeys: Set<String> = [
360	            "trial",
361	            "trail",
362	            "trace",
363	            "track",
364	            "tracks",
365	            "track_list",
366	            "trackList",
367	            "trajectory",
368	            "trajectory_list",
369	            "trajectoryList",
370	            "points",
371	            "point_list",
372	            "pointList",
373	            "gps",
374	            "gps_list",
375	            "gpsList",
376	            "location_list",
377	            "locationList",
378	            "coordinate_list",
379	            "coordinateList"
380	        ]
381	
382	        var values: [JSONValue] = []
383	
384	        func collect(_ value: JSONValue) {
385	            if let object = value.objectValue {
386	                for (key, child) in object {
387	                    if trackKeys.contains(key) {
388	                        values.append(child)
389	                    }
390	                    collect(child)
391	                }
392	            } else if let array = value.arrayValue {
393	                for child in array {
394	                    collect(child)
395	                }
396	            }
397	        }
398	
399	        collect(value)
400	        return values
401	    }
402	
403	    private static func trackPoints(from value: JSONValue) -> [NinebotInterfaceTrackPoint] {
404	        if let array = value.arrayValue {
405	            return trackPoints(fromArray: array)
406	        }
407	
408	        if let object = value.objectValue {
409	            if let point = trackPoint(fromObject: object, index: 0) {
410	                return [point]
411	            }
412	
413	            let nestedCandidates = ["trial", "trail", "trace", "track", "tracks", "points", "list", "data", "gps", "locations", "coordinates"]
414	            for key in nestedCandidates {
415	                if let child = object[key] {
416	                    let points = trackPoints(from: child)
417	                    if points.count > 1 {
418	                        return points
419	                    }
420	                }
421	            }
422	        }
423	
424	        if let string = value.stringValue {
425	            return trackPoints(fromString: string)
426	        }
427	
428	        return []
429	    }
430	
431	    private static func trackPoints(fromArray array: [JSONValue]) -> [NinebotInterfaceTrackPoint] {
432	        if let point = trackPoint(fromPair: array, index: 0) {
433	            return [point]
434	        }
435	
436	        var result: [NinebotInterfaceTrackPoint] = []
437	        for (index, value) in array.enumerated() {
438	            if let object = value.objectValue, let point = trackPoint(fromObject: object, index: index) {
439	                result.append(point)
440	                continue
441	            }
442	
443	            if let pair = value.arrayValue, let point = trackPoint(fromPair: pair, index: index) {
444	                result.append(point)
445	                continue
446	            }
447	
448	            if let string = value.stringValue {
449	                result.append(contentsOf: trackPoints(fromString: string, startIndex: result.count))
450	            }
451	        }
452	
453	        return deduplicated(result)
454	    }
455	
456	    private static func trackPoint(fromObject object: [String: JSONValue], index: Int) -> NinebotInterfaceTrackPoint? {
457	        guard let coordinate = coordinate(fromObject: object) else { return nil }
458	        return interfaceTrackPoint(
459	            coordinate: coordinate,
460	            speedKmh: normalizedSpeed(firstDouble(["speed", "spd", "speed_kmh", "speedKmh", "velocity", "v"], in: object)),
461	            auxiliaryValue: firstDouble(["direction", "bearing", "heading", "course", "angle", "aux", "auxiliary"], in: object),
462	            index: index
463	        )
464	    }
465	
466	    private static func trackPoint(fromPair pair: [JSONValue], index: Int) -> NinebotInterfaceTrackPoint? {
467	        let numbers = pair.compactMap(\.doubleValue)
468	        return trackPoint(fromNumbers: numbers, index: index)
469	    }
470	
471	    private static func trackPoints(fromString string: String, startIndex: Int = 0) -> [NinebotInterfaceTrackPoint] {
472	        let trimmed = string.trimmingCharacters(in: .whitespacesAndNewlines)
473	        guard !trimmed.isEmpty else { return [] }
474	
475	        if let jsonPoints = trackPointsFromJSONString(trimmed), jsonPoints.count > 1 {
476	            return jsonPoints
477	        }
478	
479	        let separators = CharacterSet(charactersIn: ";|\n")
480	        let segments = trimmed.components(separatedBy: separators)
481	        let points = segments.enumerated().compactMap { offset, segment -> NinebotInterfaceTrackPoint? in
482	            let numbers = segment
483	                .split { character in
484	                    character == "," || character == " " || character == "\t"
485	                }
486	                .compactMap { Double($0.trimmingCharacters(in: .whitespacesAndNewlines)) }
487	            return trackPoint(fromNumbers: numbers, index: startIndex + offset)
488	        }
489	
490	        return points.count > 1 ? deduplicated(points) : []
491	    }
492	
493	    private static func trackPointsFromJSONString(_ string: String) -> [NinebotInterfaceTrackPoint]? {
494	        guard string.first == "{" || string.first == "[" else { return nil }
495	        guard let data = string.data(using: .utf8),
496	              let value = try? JSONDecoder().decode(JSONValue.self, from: data) else {
497	            return nil
498	        }
499	        return trackPoints(from: value)
500	    }
501	
502	    private static func trackPoint(fromNumbers numbers: [Double], index: Int) -> NinebotInterfaceTrackPoint? {
503	        guard numbers.count >= 2,
504	              let coordinate = coordinate(fromPair: [.number(numbers[0]), .number(numbers[1])]) else {
505	            return nil
506	        }
507	        return interfaceTrackPoint(
508	            coordinate: coordinate,
509	            speedKmh: normalizedSpeed(numbers.count >= 3 ? numbers[2] : nil),
510	            auxiliaryValue: numbers.count >= 4 ? numbers[3] : nil,
511	            index: index
512	        )
513	    }
514	
515	    private static func interfaceTrackPoint(
516	        coordinate: CLLocationCoordinate2D,
517	        speedKmh: Double?,
518	        auxiliaryValue: Double?,
519	        index: Int
520	    ) -> NinebotInterfaceTrackPoint {
521	        NinebotInterfaceTrackPoint(
522	            id: "\(index)-\(Int((coordinate.latitude * 1_000_000).rounded()))-\(Int((coordinate.longitude * 1_000_000).rounded()))",
523	            latitude: coordinate.latitude,
524	            longitude: coordinate.longitude,
525	            speedKmh: speedKmh,
526	            auxiliaryValue: auxiliaryValue
527	        )
528	    }
529	
530	    private static func trackCoordinates(from value: JSONValue) -> [CLLocationCoordinate2D] {
531	        if let array = value.arrayValue {
532	            return coordinates(fromArray: array)
533	        }
534	
535	        if let object = value.objectValue {
536	            if let coordinate = coordinate(fromObject: object) {
537	                return [coordinate]
538	            }
539	
540	            let nestedCandidates = ["trial", "trail", "trace", "track", "tracks", "points", "list", "data", "gps", "locations", "coordinates"]
541	            for key in nestedCandidates {
542	                if let child = object[key] {
543	                    let coordinates = trackCoordinates(from: child)
544	                    if coordinates.count > 1 {
545	                        return coordinates
546	                    }
547	                }
548	            }
549	        }
550	
551	        if let string = value.stringValue {
552	            return coordinates(fromString: string)
553	        }
554	
555	        return []
556	    }
557	
558	    private static func coordinates(fromArray array: [JSONValue]) -> [CLLocationCoordinate2D] {
559	        var result: [CLLocationCoordinate2D] = []
560	
561	        for value in array {
562	            if let object = value.objectValue, let coordinate = coordinate(fromObject: object) {
563	                result.append(coordinate)
564	                continue
565	            }
566	
567	            if let pair = value.arrayValue, let coordinate = coordinate(fromPair: pair) {
568	                result.append(coordinate)
569	                continue
570	            }
571	
572	            if let string = value.stringValue {
573	                result.append(contentsOf: coordinates(fromString: string))
574	            }
575	        }
576	
577	        return deduplicated(result)
578	    }
579	
580	    private static func coordinate(fromObject object: [String: JSONValue]) -> CLLocationCoordinate2D? {
581	        let latitude = firstDouble(["lat", "latitude", "y", "gcj_lat", "gcjLat", "wgs_lat", "wgsLat"], in: object)
582	        let longitude = firstDouble(["lon", "lng", "longitude", "x", "gcj_lng", "gcjLng", "gcj_lon", "gcjLon", "wgs_lng", "wgsLng", "wgs_lon", "wgsLon"], in: object)
583	
584	        if let coordinate = coordinate(latitude: latitude, longitude: longitude) {
585	            return coordinate
586	        }
587	
588	        for key in ["location", "loc", "coordinate", "coordinates", "point", "gps"] {
589	            if let value = object[key] {
590	                let coordinates = trackCoordinates(from: value)
591	                if let first = coordinates.first {
592	                    return first
593	                }
594	            }
595	        }
596	
597	        return nil
598	    }
599

599	
600	    private static func coordinate(fromPair pair: [JSONValue]) -> CLLocationCoordinate2D? {
601	        guard pair.count >= 2,
602	              let first = pair[0].doubleValue,
603	              let second = pair[1].doubleValue else {
604	            return nil
605	        }
606	
607	        if abs(first) > 90, abs(second) <= 90 {
608	            return coordinate(latitude: second, longitude: first)
609	        }
610	
611	        return coordinate(latitude: first, longitude: second)
612	    }
613	
614	    private static func coordinates(fromString string: String) -> [CLLocationCoordinate2D] {
615	        let trimmed = string.trimmingCharacters(in: .whitespacesAndNewlines)
616	        guard !trimmed.isEmpty else { return [] }
617	
618	        if let jsonCoordinates = coordinatesFromJSONString(trimmed), jsonCoordinates.count > 1 {
619	            return jsonCoordinates
620	        }
621	
622	        let separators = CharacterSet(charactersIn: ";|\n")
623	        let segments = trimmed.components(separatedBy: separators)
624	        let coordinates = segments.compactMap { segment -> CLLocationCoordinate2D? in
625	            let parts = segment
626	                .split { character in
627	                    character == "," || character == " " || character == "\t"
628	                }
629	                .compactMap { Double($0.trimmingCharacters(in: .whitespacesAndNewlines)) }
630	            return coordinate(fromPair: parts.map { .number($0) })
631	        }
632	
633	        if coordinates.count > 1 {
634	            return deduplicated(coordinates)
635	        }
636	
637	        return []
638	    }
639	
640	    private static func coordinatesFromJSONString(_ string: String) -> [CLLocationCoordinate2D]? {
641	        guard string.first == "{" || string.first == "[" else { return nil }
642	        guard let data = string.data(using: .utf8),
643	              let object = try? JSONSerialization.jsonObject(with: data) else {
644	            return nil
645	        }
646	        return coordinates(fromAny: object)
647	    }
648	
649	    private static func coordinates(fromAny value: Any) -> [CLLocationCoordinate2D] {
650	        if let array = value as? [Any] {
651	            var result: [CLLocationCoordinate2D] = []
652	            for item in array {
653	                result.append(contentsOf: coordinates(fromAny: item))
654	            }
655	
656	            if result.isEmpty,
657	               array.count >= 2,
658	               let first = number(fromAny: array[0]),
659	               let second = number(fromAny: array[1]),
660	               let coordinate = coordinate(fromPair: [.number(first), .number(second)]) {
661	                return [coordinate]
662	            }
663	
664	            return deduplicated(result)
665	        }
666	
667	        if let object = value as? [String: Any] {
668	            if let coordinate = coordinate(fromAnyObject: object) {
669	                return [coordinate]
670	            }
671	
672	            var result: [CLLocationCoordinate2D] = []
673	            for child in object.values {
674	                result.append(contentsOf: coordinates(fromAny: child))
675	            }
676	            return deduplicated(result)
677	        }
678	
679	        return []
680	    }
681	
682	    private static func coordinate(fromAnyObject object: [String: Any]) -> CLLocationCoordinate2D? {
683	        let latitude = firstNumber(["lat", "latitude", "y", "gcj_lat", "gcjLat", "wgs_lat", "wgsLat"], in: object)
684	        let longitude = firstNumber(["lon", "lng", "longitude", "x", "gcj_lng", "gcjLng", "gcj_lon", "gcjLon", "wgs_lng", "wgsLng", "wgs_lon", "wgsLon"], in: object)
685	        return coordinate(latitude: latitude, longitude: longitude)
686	    }
687	
688	    private static func coordinate(latitude: Double?, longitude: Double?) -> CLLocationCoordinate2D? {
689	        guard let latitude,
690	              let longitude,
691	              (-90...90).contains(latitude),
692	              (-180...180).contains(longitude) else {
693	            return nil
694	        }
695	
696	        return NinebotCoordinateTransform.mapKitCoordinate(latitude: latitude, longitude: longitude)
697	    }
698	
699	    private static func firstDouble(_ keys: [String], in object: [String: JSONValue]) -> Double? {
700	        for key in keys {
701	            if let value = object[key]?.doubleValue {
702	                return value
703	            }
704	        }
705	        return nil
706	    }
707	
708	    private static func firstNumber(_ keys: [String], in object: [String: Any]) -> Double? {
709	        for key in keys {
710	            if let value = object[key], let number = number(fromAny: value) {
711	                return number
712	            }
713	        }
714	        return nil
715	    }
716	
717	    private static func number(fromAny value: Any) -> Double? {
718	        if let number = value as? NSNumber {
719	            return number.doubleValue
