3	/// How long a vehicle-history series spans, bucketed to the unit it should be
4	/// read in.
5	///
6	/// The bucket boundaries are the interesting part: a span is reported in days
7	/// only once it reaches a full day, and in hours only once it reaches a full
8	/// hour. Below that it reads in whole minutes.
9	enum NinebotHistoryPeriod: Equatable {
10	    /// First and last sample share a timestamp — there is no span yet.
11	    case justStarted
12	    case days(Double)
13	    case hours(Double)
14	    case minutes(Double)
15	
16	    /// At or above this many hours the span reads in days.
17	    static let dayBoundaryHours = 24.0
18	    /// At or above this many hours the span reads in hours rather than minutes.
19	    static let hourBoundaryHours = 1.0
20	
21	    /// - Parameter seconds: elapsed time between the first and last sample.
22	    init(seconds: TimeInterval) {
23	        guard seconds > 0 else {
24	            self = .justStarted
25	            return
26	        }
27	        let hours = seconds / 3600
28	        if hours >= Self.dayBoundaryHours {
29	            self = .days(hours / 24)
30	        } else if hours >= Self.hourBoundaryHours {
31	            self = .hours(hours)
32	        } else {
33	            self = .minutes(seconds / 60)
34	        }
35	    }
36	}
37	
38	extension NinebotVehicleHistorySummary {
39	    var period: NinebotHistoryPeriod {
40	        NinebotHistoryPeriod(seconds: latest.date.timeIntervalSince(first.date))
41	    }
42	}
