1916	enum JSONValue: Codable, Equatable {
1917	    case object([String: JSONValue])
1918	    case array([JSONValue])
1919	    case string(String)
1920	    case number(Double)
1921	    case bool(Bool)
1922	    case null
1923	
1924	    init(from decoder: Decoder) throws {
1925	        if let container = try? decoder.container(keyedBy: DynamicCodingKey.self) {
1926	            var object: [String: JSONValue] = [:]
1927	            for key in container.allKeys {
1928	                object[key.stringValue] = try container.decode(JSONValue.self, forKey: key)
1929	            }
1930	            self = .object(object)
1931	            return
1932	        }
1933	
1934	        if var container = try? decoder.unkeyedContainer() {
1935	            var array: [JSONValue] = []
1936	            while !container.isAtEnd {
1937	                array.append(try container.decode(JSONValue.self))
1938	            }
1939	            self = .array(array)
1940	            return
1941	        }
1942	
1943	        let container = try decoder.singleValueContainer()
1944	        if container.decodeNil() {
1945	            self = .null
1946	        } else if let value = try? container.decode(Bool.self) {
1947	            self = .bool(value)
1948	        } else if let value = try? container.decode(Double.self) {
1949	            self = .number(value)
1950	        } else if let value = try? container.decode(String.self) {
1951	            self = .string(value)
1952	        } else {
1953	            throw DecodingError.dataCorruptedError(in: container, debugDescription: "Unsupported JSON value")
1954	        }
1955	    }
1956	
1957	    func encode(to encoder: Encoder) throws {
1958	        switch self {
1959	        case .object(let object):
1960	            var container = encoder.container(keyedBy: DynamicCodingKey.self)
1961	            for (key, value) in object {
1962	                try container.encode(value, forKey: DynamicCodingKey(key))
1963	            }
1964	        case .array(let array):
1965	            var container = encoder.unkeyedContainer()
1966	            for value in array {
1967	                try container.encode(value)
1968	            }
1969	        case .string(let string):
1970	            var container = encoder.singleValueContainer()
1971	            try container.encode(string)
1972	        case .number(let number):
1973	            var container = encoder.singleValueContainer()
1974	            try container.encode(number)
1975	        case .bool(let bool):
1976	            var container = encoder.singleValueContainer()
1977	            try container.encode(bool)
1978	        case .null:
1979	            var container = encoder.singleValueContainer()
1980	            try container.encodeNil()
1981	        }
1982	    }
1983	
1984	    var objectValue: [String: JSONValue]? {
1985	        guard case .object(let object) = self else { return nil }
1986	        return object
1987	    }
1988	
1989	    var arrayValue: [JSONValue]? {
1990	        guard case .array(let array) = self else { return nil }
1991	        return array
1992	    }
1993	
1994	    var stringValue: String? {
1995	        switch self {
1996	        case .string(let string):
1997	            return string
1998	        case .number(let number):
1999	            if number.rounded() == number {
2000	                return String(Int(number))
2001	            }
2002	            return String(number)
2003	        case .bool(let bool):
2004	            return bool ? "true" : "false"
2005	        default:
2006	            return nil
2007	        }
2008	    }
2009	
2010	    var doubleValue: Double? {
2011	        switch self {
2012	        case .number(let number):
2013	            return number
2014	        case .string(let string):
2015	            return Double(string)
2016	        case .bool(let bool):
2017	            return bool ? 1 : 0
2018	        default:
2019	            return nil
2020	        }
2021	    }
2022	
2023	    var intValue: Int? {
2024	        guard let doubleValue else { return nil }
2025	        return Int(doubleValue)
2026	    }
2027	
2028	    var boolValue: Bool? {
2029	        switch self {
2030	        case .bool(let bool):
2031	            return bool
2032	        case .number(let number):
2033	            return number != 0
2034	        case .string(let string):
2035	            let normalized = string.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
2036	            if ["1", "true", "yes", "on"].contains(normalized) { return true }
2037	            if ["0", "false", "no", "off"].contains(normalized) { return false }
2038	            return nil
2039	        default:
2040	            return nil
2041	        }
2042	    }
2043	
2044	    subscript(key: String) -> JSONValue? {
2045	        objectValue?[key]
2046	    }
2047	
2048	    var displayText: String {
2049	        switch self {
2050	        case .object(let object):
2051	            if object.isEmpty { return "{}" }
2052	            return object
2053	                .sorted { $0.key < $1.key }
2054	                .map { "\($0.key): \($0.value.displayText)" }
2055	                .joined(separator: ", ")
2056	        case .array(let array):
2057	            if array.isEmpty { return "[]" }
2058	            return array.map(\.displayText).joined(separator: ", ")
2059	        case .string(let string):
2060	            return string
2061	        case .number(let number):
2062	            if number.rounded() == number {
2063	                return String(Int(number))
2064	            }
2065	            return String(number)
2066	        case .bool(let bool):
2067	            return bool ? "true" : "false"
2068	        case .null:
2069	            return "null"
2070	        }
2071	    }
2072	}
