2081	    }
2082	
2083	    init(_ intValue: Int) {
2084	        self.stringValue = "\(intValue)"
2085	        self.intValue = intValue
2086	    }
2087	
2088	    init?(stringValue: String) {
2089	        self.init(stringValue)
2090	    }
2091	
2092	    init?(intValue: Int) {
